#!/usr/bin/env bash
# Conversión de plantillas personalizadas de oficios. Sólo el renderer; sin SQL ni cambios de módulos.
set -euo pipefail
MODE="${1:---check}"
[[ ( "$#" -le 1 && ( "$MODE" == --check || "$MODE" == --apply || "$MODE" == --probe ) ) || ( "$MODE" == --restore && "$#" == 2 ) ]] || { echo 'Uso: --check | --apply | --probe | --restore RUTA' >&2;exit 2; }
VERSION='oficios-personalizados-v1'
FILES=('app/services/OficioRedmexPdfRenderer.php')
LIVE="${IMPE_OFICIOS_PDF_PUBLIC:-$HOME/domains/fundacionrededumex.org/public_html}"
BACKUPS="${IMPE_OFICIOS_PDF_BACKUPS:-$HOME/respaldos-crm}"
fail(){ echo "ERROR: $*" >&2;exit 1; }
hash(){ sha256sum "$1" | cut -d' ' -f1; }
no_links(){ local part="$1";while [[ "$part" != / && "$part" != . ]];do
 [[ ! -L "$part" ]] || fail "Enlace simbólico no permitido: $1"
 case "$part" in */*) part="${part%/*}";[[ -n "$part" ]] || part=/;; *) part=.;;esac
done; }
for tool in php sha256sum cut mktemp realpath cp mv mkdir rm rmdir dirname date chmod;do command -v "$tool" >/dev/null || fail "Falta $tool";done
no_links "$LIVE";[[ -d "$LIVE" ]] || fail 'Raíz del CRM no encontrada.'
LIVE="$(cd "$LIVE" && pwd -P)";[[ -f "$LIVE/index.php" ]] || fail 'Falta el índice del CRM.'
for file in "${FILES[@]}";do no_links "$LIVE/$file";[[ -f "$LIVE/$file" ]] || fail "Falta $file";done
no_links "$BACKUPS";BACKUPS="$(realpath -m "$BACKUPS")"
[[ "$BACKUPS" != / && "$BACKUPS/" != "$LIVE/"* && "$LIVE/" != "$BACKUPS/"* ]] || fail 'El respaldo debe estar fuera del sitio y sus antecesores.'
SCRATCH="$(cd "${TMPDIR:-/tmp}" && pwd -P)";[[ "$SCRATCH/" != "$LIVE/"* ]] || fail 'Temporales fuera del sitio requeridos.'
TMP="$(mktemp -d "$SCRATCH/impe-oficios-personalizados.XXXXXX")"
LOCK="$(dirname "$LIVE")/.impe-correos-deploy.lock";LOCKED=0;INSTALLING=-1
BEFORE=();AFTER=();WRITTEN=();CHANGED=()
finish(){ local code=$?;trap - EXIT INT TERM
 if [[ "$code" != 0 ]];then
  for i in "${WRITTEN[@]}";do
   if [[ -f "$LIVE/${FILES[$i]}" && "$(hash "$LIVE/${FILES[$i]}")" == "${AFTER[$i]}" ]];then
    cp -p -- "$TMP/original.$i" "$LIVE/${FILES[$i]}" || echo 'REVISAR RESTAURACIÓN DEL ARCHIVO' >&2
   else echo "REVISAR: archivo cambiado durante la publicación: ${FILES[$i]}" >&2;fi
  done
 fi
 if [[ "$INSTALLING" != -1 ]];then rm -f -- "$LIVE/${FILES[$INSTALLING]}.impe-oficios-personalizados-$$";fi
 [[ "$LOCKED" == 0 ]] || rmdir -- "$LOCK"
 rm -f -- "$TMP/original.0" "$TMP/stage.0" "$TMP/patch.php" "$TMP/probe.php"
 rmdir -- "$TMP";exit "$code"
}
trap finish EXIT;trap 'exit 130' INT;trap 'exit 143' TERM
if [[ "$MODE" != --check && "$MODE" != --probe ]];then no_links "$LOCK";mkdir "$LOCK" 2>/dev/null || fail 'Otra publicación está en curso.';LOCKED=1;fi
if [[ "$MODE" == --probe ]];then
 cat > "$TMP/probe.php" <<'IMPE_PROBE'
<?php
if(PHP_SAPI!=='cli')exit(1);
$root=realpath($argv[1]);$dir=null;$status=0;
try{
 require $root.'/app/services/OficioRedmexPdfRenderer.php';
 if(!defined('OficioRedmexPdfRenderer::VERSION')||OficioRedmexPdfRenderer::VERSION!=='20261026-personalizadas-1')throw new RuntimeException('Sigue instalado el conversor anterior.');
 echo 'VERSION=',OficioRedmexPdfRenderer::VERSION,PHP_EOL;
 $base=realpath($root.'/storage/templates/oficios_personalizados');$source=null;
 foreach(glob($base.'/*.docx')?:[] as $path){
  if(is_link($path)||dirname(realpath($path))!==$base)continue;
  if(hash_file('sha256',$path)==='f227897c24b7fa08145a6f38b529e208c5c383011647af2a7f9999f0751bc45f'){$source=$path;break;}
 }
 if(!$source)throw new RuntimeException('No se encontró la copia exacta de Embajadas validada; prueba la plantilla seleccionada desde el CRM.');
 $before=hash_file('sha256',$source);
 $dir=sys_get_temp_dir().'/impe-oficios-personalizados-probe-'.bin2hex(random_bytes(8));
 if(!mkdir($dir,0700))throw new RuntimeException('No se pudo preparar el temporal.');
 $r=(new OficioRedmexPdfRenderer())->convertir($source,$dir);
 if(!($r['ok']??false))throw new RuntimeException((string)($r['mensaje_tecnico']??'CONVERSION_ERROR'));
 if(hash_file('sha256',$source)!==$before)throw new RuntimeException('Original alterado.');
 $pdf=file_get_contents($r['ruta_pdf']);
 if(!str_starts_with($pdf,'%PDF-')||!preg_match('/%%EOF\s*$/D',substr($pdf,-1024)))throw new RuntimeException('PDF inválido.');
 echo 'PDF_BYTES=',strlen($pdf),PHP_EOL,'ORIGINAL_INTACTO=SI',PHP_EOL;
 echo "OK: conversión real de la plantilla Embajadas; PDF temporal retirado. Sin BD ni envíos. La vista previa web debe verificarse en el CRM.\n";
}catch(Throwable $e){fwrite(STDERR,'ERROR: '.$e->getMessage().PHP_EOL);$status=1;}
finally{
 if($dir&&is_dir($dir)){
  $remove=function($p)use(&$remove){foreach(scandir($p)as$n){if($n==='.'||$n==='..')continue;$f=$p.'/'.$n;if(is_dir($f)&&!is_link($f))$remove($f);else unlink($f);}rmdir($p);};$remove($dir);
 }
}
exit($status);
IMPE_PROBE
 php -d memory_limit=128M "$TMP/probe.php" "$LIVE"
 exit $?
fi
if [[ "$MODE" != --restore ]];then
 [[ -f "$LIVE/vendor/autoload.php" ]] || fail 'Falta vendor/autoload.php.'
 php -r 'require $argv[1]."/vendor/autoload.php";foreach(["ZipArchive","DOMDocument","Dompdf\\Dompdf","FontLib\\Font"]as$c)if(!class_exists($c))exit(1);exit(extension_loaded("gd")&&function_exists("mb_str_split")?0:1);' "$LIVE" || fail 'Faltan dependencias PHP del conversor. No se modifica vendor.'
 php -r '$s=file_get_contents($argv[1]."/app/services/OficioDocxPdfService.php");exit(strpos($s,"new OficioRedmexPdfRenderer()")!==false?0:1);' "$LIVE" || fail 'El servicio instalado no utiliza el conversor REDMEX. SITIO INTACTO.'
fi
for i in "${!FILES[@]}";do BEFORE[$i]="$(hash "$LIVE/${FILES[$i]}")";cp -p -- "$LIVE/${FILES[$i]}" "$TMP/original.$i";done
if [[ "$MODE" == --restore ]];then
 no_links "$2";RESTORE="$(realpath -e "$2")"
 [[ "$(dirname "$RESTORE")" == "$BACKUPS" ]] || fail 'Respaldo fuera de la carpeta prevista.'
 no_links "$RESTORE/version.txt";[[ -f "$RESTORE/version.txt" && "$(<"$RESTORE/version.txt")" == "$VERSION" ]] || fail 'Respaldo de otra entrega.'
 for i in "${!FILES[@]}";do
  for file in "original.$i" "original.$i.sha256" "publicado.$i.sha256";do no_links "$RESTORE/$file";[[ -f "$RESTORE/$file" ]] || fail 'Respaldo incompleto.';done
  original="$(<"$RESTORE/original.$i.sha256")";published="$(<"$RESTORE/publicado.$i.sha256")"
  [[ "$original" =~ ^[a-f0-9]{64}$ && "$published" =~ ^[a-f0-9]{64}$ && "$(hash "$RESTORE/original.$i")" == "$original" ]] || fail 'Respaldo alterado.'
  [[ "${BEFORE[$i]}" == "$published" || "${BEFORE[$i]}" == "$original" ]] || fail 'Archivo editado después de publicar. No se sobrescribe.'
  cp -p -- "$RESTORE/original.$i" "$TMP/stage.$i"
 done
else
 cat > "$TMP/patch.php" <<'IMPE_PATCH'
<?php
$s=file_get_contents($argv[2]);$crlf=substr_count($s,"\r\n");
if($crlf&&$crlf!==substr_count($s,"\n"))throw new RuntimeException('Finales de línea mixtos.');
$s=str_replace("\r\n","\n",$s);
if(!in_array(hash('sha256',$s),['caad6f5fb35592e9cd2bb14d6c18f75196d25ffe43555366b7f571e7f232d2aa','825f4aeece29d41de8e57a0098b5d0f8551dd83d31feb93c192b5994ca9c8ee5','9c82890dcc0fd519634ad60f328da86e588f8d1ebd55a4a133cd30e4d376aee3'],true))throw new RuntimeException('Conversor personalizado o incompatible; no se sobrescribe.');
$s=base64_decode('',true);
if(!is_string($s)||hash('sha256',$s)!=='9c82890dcc0fd519634ad60f328da86e588f8d1ebd55a4a133cd30e4d376aee3')throw new RuntimeException('Entrega alterada.');
if($crlf)$s=str_replace("\n","\r\n",$s);
if(file_put_contents($argv[3],$s)!==strlen($s))throw new RuntimeException('No se pudo preparar el archivo.');
IMPE_PATCH
 for i in "${!FILES[@]}";do php "$TMP/patch.php" "$i" "$TMP/original.$i" "$TMP/stage.$i" || fail 'Conversor incompatible. SITIO INTACTO.';chmod --reference="$TMP/original.$i" "$TMP/stage.$i";done
fi
for i in "${!FILES[@]}";do php -l "$TMP/stage.$i" >/dev/null || fail 'Error de sintaxis en el servicio preparado.';done
for i in "${!FILES[@]}";do
 no_links "$LIVE/${FILES[$i]}";[[ "$(hash "$LIVE/${FILES[$i]}")" == "${BEFORE[$i]}" ]] || fail 'Un archivo cambió durante la revisión.'
 AFTER[$i]="$(hash "$TMP/stage.$i")";[[ "${AFTER[$i]}" == "${BEFORE[$i]}" ]] || CHANGED+=("$i")
done
if [[ "${#CHANGED[@]}" == 0 ]];then echo 'OK: ya aplicado o restaurado. Ningún archivo reemplazado.';exit 0;fi
if [[ "$MODE" == --check ]];then echo 'OK: revisión compatible. Sólo OficioRedmexPdfRenderer.php; versión 20261026-personalizadas-1. SITIO INTACTO. Sin envíos ni SQL.';exit 0;fi
if [[ "$MODE" == --apply ]];then
 mkdir -p "$BACKUPS";BACKUP="$BACKUPS/oficios-personalizados-$(date +%Y%m%d-%H%M%S)-$$";(umask 077;mkdir "$BACKUP")
 for i in "${!FILES[@]}";do
  cp -p -- "$TMP/original.$i" "$BACKUP/original.$i";[[ "$(hash "$BACKUP/original.$i")" == "${BEFORE[$i]}" ]] || fail 'Respaldo inconsistente.'
  printf '%s\n' "${BEFORE[$i]}" > "$BACKUP/original.$i.sha256";printf '%s\n' "${AFTER[$i]}" > "$BACKUP/publicado.$i.sha256"
 done
 printf '%s\n' "$VERSION" > "$BACKUP/version.txt"
fi
for i in "${CHANGED[@]}";do
 install="$LIVE/${FILES[$i]}.impe-oficios-personalizados-$$";[[ ! -e "$install" && ! -L "$install" ]] || fail 'Existe un temporal de instalación.'
 INSTALLING="$i";cp -p -- "$TMP/stage.$i" "$install"
 for j in "${CHANGED[@]}";do
  expected="${BEFORE[$j]}";for done_i in "${WRITTEN[@]}";do [[ "$done_i" != "$j" ]] || expected="${AFTER[$j]}";done
  no_links "$LIVE/${FILES[$j]}";[[ "$(hash "$LIVE/${FILES[$j]}")" == "$expected" ]] || fail 'Un archivo cambió antes de instalar.'
 done
 WRITTEN+=("$i");mv -f -- "$install" "$LIVE/${FILES[$i]}";INSTALLING=-1
 [[ "$(hash "$LIVE/${FILES[$i]}")" == "${AFTER[$i]}" ]] || fail 'Archivo instalado distinto.'
done
echo "OK: $MODE terminado. Conversor de oficios actualizado. Sin SQL ni cambios de plantillas, módulos, folios o configuración."
if [[ "$MODE" == --apply ]];then echo "Respaldo: $BACKUP";printf 'Rollback: bash %q --restore %q\n' "$(realpath "$0")" "$BACKUP";fi
